export default {
  version: "2025-10-31",
  label: "October 2025",
  releaseDate: "2025-10-31",
  entries: [
    { id: "1", type: "chapter", title: "Concepts", slug: "concepts" },
    { id: "1.1", type: "rule", title: "General" },
    { id: "1.1.1", type: "rule", text: "Disney Lorcana cards are published in multiple languages. For the purposes of gameplay, the English cards, rules, rulings, and clarifications are the official versions." },
    { id: "1.1.2", type: "rule", text: "Card text and rules may be updated or corrected. The most current updated or corrected information is the official version for gameplay." },
    { id: "1.1.3", type: "rule", text: "The Disney Lorcana TCG is a game played with two or more people. Each player needs a deck of Disney Lorcana cards that they’ll use in the game. See 2.1 “Deck Rules” for deck requirements." },
    { id: "1.1.4", type: "rule", text: "Each player needs a way to track their lore totals and mark damage on characters and locations. This can be any method players find convenient that is clear to all players in the game." },
    { id: "1.1.5", type: "rule", text: "Disney Lorcana tournaments may have additional rules that can affect the ones in this document. Please refer to the Disney Lorcana TCG Tournament Rules found here for further reference." },
    { id: "1.1.6", type: "rule", text: "Some cards include reminder text set in italics. Reminder text isn’t rules text. It’s only a memory aid and may vary without changing the meaning of keyword rules." },
    { id: "1.2", type: "rule", title: "Golden Rules" },
    { id: "1.2.1", type: "rule", text: "If the text of a card contradicts a game rule, the card effect supersedes that rule.\n\nExample: The game doesn’t allow a character to challenge a ready character, but a player has a character with an ability that reads, “This character can challenge ready characters.” The ability overrides the game rule and allows that character to challenge a ready character." },
    { id: "1.2.2", type: "rule", text: "If a rule or effect prevents something from happening, that rule or effect supersedes other rules and effects that allow it to happen.\n\nExample: An effect says that players can’t play actions. Another effect instructs a player they may play an action for free. That player still can’t play an action." },
    { id: "1.2.3", type: "rule", text: "Do as much as you can – If an effect tells a player to do something, the player does as much as possible even if some part of that effect can’t be done, except in specific cases (see 7.1.2).\n\nExample: Strike a Good Match has an effect that reads, “Draw 2 cards, then choose and discard a card.” If an effect prevents the player of this action from drawing any cards, they still have to choose and discard a card." },
    { id: "1.2.4", type: "rule", text: "Choices that are made as a part of an effect are made as the effect is resolving and not as part of playing the card or using the ability with the effect.\n\nExample: The active player has a Let the Storm Rage On in their hand and no characters in play. The opponent has a Cogsworth – Grandfather Clock (which has Ward) in play and has no other characters in play. Let the Storm Rage On has an effect that reads, “Deal 2 damage to chosen character. Draw a card.” When the active player plays Let the Storm Rage On, the opponent isn’t sure they can play it, since there are no characters in play for them to choose. The choice of character happens as the effect is resolving, though, not when the card is played. Because the active player can’t choose Cogsworth as the effect is resolving, they do as much as they can and draw a card without dealing 2 damage." },
    { id: "1.3", type: "rule", title: "Active Player" },
    { id: "1.3.1", type: "rule", text: "When a player starts their turn, they become the active player. When a player ends their turn, they’re no longer the active player." },
    { id: "1.4", type: "rule", title: "Opponent" },
    { id: "1.4.1", type: "rule", text: "Anyone a player is playing against is their opponent." },
    { id: "1.4.2", type: "rule", text: "Some game formats allow a player to designate one or more players as teammates. Such teammates are identified before the game starts. As teammates aren’t playing against each other, they aren’t opponents to one another." },
    { id: "1.5", type: "rule", title: "Playing Cards" },
    { id: "1.5.1", type: "rule", text: "Players can play a card whenever they’re the active player and there are no effects to resolve. To play a card, the player reveals it from their hand and pays the cost (see 4.3.4)." },
    { id: "1.6", type: "rule", title: "Types of Abilities" },
    { id: "1.6.1", type: "rule", text: "There are several kinds of abilities in the Disney Lorcana TCG." },
    { id: "1.6.1.1", type: "rule", text: "Keywords are words or shortened phrases that represent a larger ability or abilities. See section 10 for the full list of current keywords." },
    { id: "1.6.1.2", type: "rule", text: "Triggered abilities continuously look for a specific condition and have an effect when that condition is met. Triggered abilities follow the rules in section 7.4." },
    { id: "1.6.1.3", type: "rule", text: "Activated abilities have a cost and an effect that occurs if that cost is paid. Activated abilities follow the rules in section 7.5." },
    { id: "1.6.1.4", type: "rule", text: "Static abilities are effects that are continuously active, either for a fixed length of time or for as long as the card generating the effect is in play. Static abilities follow the rules in section 7.6." },
    { id: "1.6.1.5", type: "rule", text: "Replacement effects are generated by some abilities. These replace one effect with another. Replacement effects follow the rules in section 7.7." },
    { id: "1.6.2", type: "rule", text: "Whenever an effect would affect multiple players at the same time, the active player resolves that effect first, then in turn order each other player resolves that effect.\n\nExample: Donald Duck – Perfect Gentleman has the ability Allow Me that reads, “At the start of your turn, each player may draw a card.” While the triggered ability is resolving, the active player resolves their part of the effect first and draws a card. Then in turn order each other player resolves their part of the effect and draws a card. Once all players have finished resolving their respective parts of the effect, it has fully resolved and the game continues." },
    { id: "1.7", type: "rule", title: "The Bag" },
    { id: "1.7.1", type: "rule", text: "The bag is the zone where triggered abilities wait to resolve. It’s not a physical zone but a way to picture the process of resolving triggered abilities. Think of each triggered ability as a marble and the bag as a place to put them until they’re resolved. Every marble is separate from every other marble, and a player can look through the bag of marbles to select the one they wish to resolve next." },
    { id: "1.7.2", type: "rule", text: "It’s possible for both the active player and their opponent(s) to add triggered abilities to the bag at the same time. Resolving these abilities follows the rules in section 8.7, “Bag.”" },
    { id: "1.8", type: "rule", title: "Players’ Cards" },
    { id: "1.8.1", type: "rule", text: "Cards a player brings to the table in their deck are their cards, and that player makes any decisions necessary for the card and its effects unless otherwise specified by an effect." },
    { id: "1.8.2", type: "rule", text: "His/Her/Its/Their – When a card refers to “his,” “her,” “its,” or “their” player, it’s referring to the person who played the card. When a card refers to “his,” “her,” “its,” or “their” turn, it’s referring to its player’s turn." },
    { id: "1.8.3", type: "rule", text: "You/Your/Yours – Card effects address the player who played that card. When a card refers to “you,” “your,” or “yours,” it’s referring to the player of the card, even if the ability containing the reference was granted by an opposing effect." },
    { id: "1.9", type: "rule", title: "Game State Check" },
    { id: "1.9.1", type: "rule", text: "There is a set of conditions the game checks for with certain required actions happening when one or more of those conditions is met. This is called a game state check and is made up of two parts: the game state condition and the required action. A game state condition is a specific circumstance the game state can achieve. A required action is what happens in the game when a game state condition is met. The following are the conditions that the game state check looks for and the required action each creates." },
    { id: "1.9.1.1", type: "rule", text: "If a player has 20 or more lore, that player wins the game." },
    { id: "1.9.1.2", type: "rule", text: "If a player attempted to draw from a deck with no cards since the last game state check, that player loses the game." },
    { id: "1.9.1.3", type: "rule", text: "If a character or location has damage equal to or greater than its Willpower {W}, that character or location is banished. A character or location banished as a result of damage dealt by a character in a challenge since the last game state check or as a result of damage dealt, put, or moved by a character’s ability since the last game state check is considered banished by that character." },
    { id: "1.9.2", type: "rule", text: "A game state check is made at the end of every step, after any action or ability is finished resolving, and after each effect in the bag is finished resolving. During a game state check, first check and complete all win and loss conditions and required actions. Then if there are no win or loss conditions met, check and complete all other conditions and required actions. Once all required actions are complete, the game state check repeats until there are no further required actions to complete. Triggered abilities that occurred during this process are then added to the bag to resolve." },
    { id: "1.9.2.1", type: "rule", text: "Any required actions generated from a game state check happen in turn order. If a player would win and lose the game at the same time as a result of the same game state check, that player wins the game." },
    { id: "1.9.3", type: "rule", text: "Once a required action is completed, the game state check occurs again." },
    { id: "1.9.4", type: "rule", text: "Abilities that trigger as a result of a game state check are added to the bag as soon as the check and any required actions are fully completed." },
    { id: "1.9.5", type: "rule", text: "If multiple required actions would happen at once, a single combined required action takes place, and all of the required actions happen simultaneously." },
    { id: "1.10", type: "rule", title: "Multiplayer Games" },
    { id: "1.10.1", type: "rule", text: "Multiplayer games are played with three or more players. Team games are a subset of multiplayer play that are not covered in this document." },
    { id: "1.10.2", type: "rule", text: "Multiplayer games follow the same rules as two-player games, with the following exceptions." },
    { id: "1.10.2.1", type: "rule", text: "At the end of each player’s turn, play proceeds to the player on their left rather than going back and forth across the table." },
    { id: "1.10.2.2", type: "rule", text: "If an ability requires more than one player to do something at the same time, the active player does it first. Then proceed to the left, one player at a time, until all players are done." },
    { id: "1.10.2.3", type: "rule", text: "After a player loses the game from attempting to draw from a deck with no cards (see 1.9.1.2), they must leave the game immediately. All of that player’s cards and effects are removed from the game, including any static effects that would have ended during their current or future turns as well as any triggered abilities that player added to the bag that haven’t resolved." },
    { id: "1.10.3", type: "rule", text: "Some multiplayer game formats use simultaneous turns." },
    { id: "1.10.3.1", type: "rule", text: "During a simultaneous turn, all players on the same team progress through the phases and steps of the game at the same time. During the Main Phase, the players can take any turn action they could take normally in any player order they wish. Players must complete one turn action in its entirety before moving to the next turn action." },
    { id: "1.10.3.2", type: "rule", text: "If triggered abilities or effects are added to the bag by multiple players during a simultaneous turn, these triggered abilities or effects are added to the bag by the team as a whole, and the order in which they are resolved is chosen by the team. Otherwise, resolving follows the same rules found in section 8.7, “Bag.”\n\nExample: Three players are members of the same team taking a simultaneous turn. During the Ready step of the Beginning Phase, all three players ready their cards at the same time. During the Set step, all three players gain lore from locations they have in play with a {L} characteristic and then add any effects or abilities that triggered during the Ready step to the bag at the same time. In the Draw step, all three players draw a card from their decks at the same time. After the game moves into the Main Phase, the players take a simultaneous turn together. The first player wants to put a card into their inkwell. The second wants to quest, and the third has decided to have one of their characters challenge an opposing character. The players can decide the order of these turn actions, but each turn action must be completed in its entirety before the next player can act. During the End of Turn Phase, the players declare the end of their turn. All triggers are added to the bag at the same time and all “this turn” effects end at the same time." },

    { id: "2", type: "chapter", title: "Before the Game", slug: "before-the-game" },
    { id: "2.1", type: "rule", title: "Deck Rules" },
    { id: "2.1.1", type: "rule", text: "Each player’s Disney Lorcana deck must meet the following requirements. Alternate play formats may have different requirements." },
    { id: "2.1.1.1", type: "rule", text: "The deck must contain at least 60 cards. There’s no upper limit to the number of cards in a deck." },
    { id: "2.1.1.2", type: "rule", text: "The deck can’t contain more than two ink types." },
    { id: "2.1.1.3", type: "rule", text: "The deck can’t contain more than 4 cards with the same full name (see 6.2.4)." },
    { id: "2.1.1.4", type: "rule", text: "The deck can’t contain any banned cards." },

    { id: "3", type: "chapter", title: "Gameplay", slug: "gameplay" },
    { id: "3.1", type: "rule", title: "Starting a Game" },
    { id: "3.1.1", type: "rule", text: "Starting a game involves several steps that all players follow. Once these steps are completed, the game is considered to be started." },
    { id: "3.1.2", type: "rule", text: "First, use a method for randomly determining who chooses who is the starting player and takes the first turn of the game. This can include rolling dice, flipping a coin, or other methods. If this game is next in a best-of series (such as a best-of-three), the losing player of the previous game chooses the starting player." },
    { id: "3.1.3", type: "rule", text: "Second, each player randomizes (shuffles) their deck. Players may use any form of randomization they find convenient and comfortable, but the method chosen must sufficiently randomize the deck. Each player must offer an opposing player a chance to cut their deck after it’s shuffled. Once these steps are complete, the deck is ready to play and is placed in the play area." },
    { id: "3.1.4", type: "rule", text: "Third, each player begins the game with 0 lore. Players may use any method for tracking their lore, such as pen and paper, lore trackers, or the official Disney Lorcana Trading Card Game Companion app." },
    { id: "3.1.5", type: "rule", text: "Fourth, each player draws 7 cards." },
    { id: "3.1.6", type: "rule", text: "Fifth, players may alter their hands, beginning with the starting player. Each player can alter their hand only once in each game, following the steps listed here." },
    { id: "3.1.6.1", type: "rule", text: "Step 1 – The player selects any number of cards from their hand and places them on the bottom of their deck without revealing them." },
    { id: "3.1.6.2", type: "rule", text: "Step 2 – The player draws until they have 7 cards in their hand." },
    { id: "3.1.6.3", type: "rule", text: "Step 3 – In turn order, each other player completes steps 1 and 2 if they choose to alter their hand." },
    { id: "3.1.6.4", type: "rule", text: "Step 4 – Each player who altered their hand by 1 or more cards shuffles their deck." },
    { id: "3.1.6.5", type: "rule", text: "Step 5 – Each player who altered their hand offers an opposing player a chance to cut their deck. Note that some play events may allow additional randomizing methods or require specific ones." },
    { id: "3.1.7", type: "rule", text: "Once all players have altered or chosen not to alter their hand, the game officially starts with the starting player’s Beginning Phase (see 4.2)." },
    { id: "3.1.8", type: "rule", text: "Certain formats and tournament policies may add to, remove from, or otherwise adjust these rules." },
    { id: "3.2", type: "rule", title: "Ending a Game" },
    { id: "3.2.1", type: "rule", text: "A game can end one of these ways:" },
    { id: "3.2.1.1", type: "rule", text: "When a player reaches 20 lore, they win the game." },
    { id: "3.2.1.2", type: "rule", text: "If a player attempted to draw from a deck with no cards since the last game state check, that player loses the game. All cards in play and any abilities or effects waiting to resolve that belong to a player who loses the game are immediately removed. If this occurs in a multiplayer game, the game continues. If it was the losing player’s turn, the game progresses to the next player’s turn after any other effects have been resolved." },
    { id: "3.2.1.3", type: "rule", text: "If a player is the last person left in a game, they win the game." },

    { id: "4", type: "chapter", title: "Turn Structure", slug: "turn-structure" },
    { id: "4.1", type: "rule", title: "Phases" },
    { id: "4.1.1", type: "rule", text: "A turn has three phases, which occur in this order: Beginning Phase, Main Phase, and End of Turn Phase." },
    { id: "4.1.2", type: "rule", text: "The Beginning Phase is where a player resets their cards as appropriate for their new turn. This is where all effects that end at the start of the player’s turn end and where effects that occur or begin at the start of their turn happen. The Beginning Phase has three steps: Ready, Set, and Draw. (See 4.2, “Beginning Phase.”)" },
    { id: "4.1.3", type: "rule", text: "The Main Phase is where a player can act on their turn, choosing to perform any of the Main Phase turn actions. (See 4.3, “Main Phase.”)" },
    { id: "4.1.4", type: "rule", text: "The End of Turn Phase is where all effects that end at the current turn end. If effects would be added to the bag as a result of effects ending, those effects are resolved and the game proceeds to the next player’s Beginning Phase. (See 4.4, “End of Turn Phase.”)" },
    { id: "4.2", type: "rule", title: "Beginning Phase" },
    { id: "4.2.1", type: "rule", text: "Ready" },
    { id: "4.2.1.1", type: "rule", text: "The active player readies all their cards in play and in their inkwell." },
    { id: "4.2.1.2", type: "rule", text: "Effects that apply “During your turn” start applying." },
    { id: "4.2.1.3", type: "rule", text: "Effects that end “at the start of your turn” or “at the start of your next turn” end." },
    { id: "4.2.1.4", type: "rule", text: "Effects that trigger “at the start of your turn” and “at the beginning of your turn” trigger but do not yet resolve (see 4.2.2.3)." },
    { id: "4.2.2", type: "rule", text: "Set" },
    { id: "4.2.2.1", type: "rule", text: "Characters that are in play are no longer “drying” and will be able to quest, challenge, or {E} to pay costs for activated abilities or song cards." },
    { id: "4.2.2.2", type: "rule", text: "The active player gains lore from locations they have in play with a {L} characteristic. This isn’t a triggered ability and doesn’t use the bag." },
    { id: "4.2.2.3", type: "rule", text: "Effects that would occur “At the start of your turn” or “At the beginning of your turn” and abilities that triggered during the Ready step are added to the bag. Then, all triggers are resolved." },
    { id: "4.2.3", type: "rule", text: "Draw" },
    { id: "4.2.3.1", type: "rule", text: "Drawing is when a player takes the top card of their deck and puts that card into their hand. A player can draw only from their deck. Putting a card into a hand from any zone besides the deck isn’t considered drawing." },
    { id: "4.2.3.2", type: "rule", text: "First, the active player draws a card from their deck. If this turn is the first turn of the game, the active player skips this step." },
    { id: "4.2.3.3", type: "rule", text: "Once all effects have been resolved and there are no more waiting to be added, the game moves into the Main Phase." },
    { id: "4.3", type: "rule", title: "Main Phase" },
    { id: "4.3.1", type: "rule", text: "Turn actions are the actions that the game allows a player to take during their turn. No effect or other card is needed in order to take these turn actions." },
    { id: "4.3.2", type: "rule", text: "The active player may take turn actions in any order during the Main Phase of their turn. Unless otherwise noted, they may take each action any number of times, provided they have the necessary resources to pay any associated costs and complete the turn actions." },
    { id: "4.3.3", type: "rule", text: "Put a card into the inkwell. This turn action is limited to once per turn." },
    { id: "4.3.3.1", type: "rule", text: "The player declares they’re putting a card into their inkwell, then chooses and reveals a card from their hand with the inkwell symbol. All players verify that the inkwell symbol is present." },
    { id: "4.3.3.2", type: "rule", text: "The player places the revealed card in their inkwell facedown and ready." },
    { id: "4.3.3.3", type: "rule", text: "Effects that would occur as a result of a card being put into the inkwell are added to the bag (see 8.7, “Bag”)." },
    { id: "4.3.4", type: "rule", text: "Play a card." },
    { id: "4.3.4.1", type: "rule", text: "The active player can take a turn action to play a card from their hand by announcing the card and paying its cost. This process follows a series of steps. If any part of the playing a card process can’t be performed, it’s illegal to play the card and the game goes back to the point right before the card was announced." },
    { id: "4.3.4.2", type: "rule", text: "These steps apply to all cards that can be played. Cards can normally be played only from a player’s hand. Only the active player can play cards; no player may play a card on an opponent’s turn." },
    { id: "4.3.4.3", type: "rule", text: "First, the active player announces the card they intend to play and reveals it from their hand." },
    { id: "4.3.4.4", type: "rule", text: "Second, the player announces how they intend to play the card, whether for its ink cost or an alternate cost. If multiple alternate costs could apply to the card, the player may choose one and ignore the others for the purposes of playing the card." },
    { id: "4.3.4.5", type: "rule", text: "Third, the player determines the total cost needed to play the card. The total cost is the ink cost or alternate cost plus any cost modifiers. This can include additional costs, cost increases, or cost reductions. Apply any additional costs first, then cost increases, then cost reductions. The resulting cost is the total cost." },
    { id: "4.3.4.6", type: "rule", text: "Fourth, the player pays the total cost. If the total cost includes any ink, the player must exert a number of ready ink cards equal to the ink cost. If any other costs are included, the player pays those costs as instructed by the card text. Costs can be paid in any order but must be paid in full." },
    { id: "4.3.4.7", type: "rule", text: "Once the total card cost is paid, the card is now “played.” If the card is a character, item, or location, the card enters the Play zone. If it’s a character being played using its Shift ability, it must be put on top of the card indicated in the second step of this process. If the card is an action, the effect immediately resolves and the card goes to the player’s discard pile." },
    { id: "4.3.4.8", type: "rule", text: "If an effect would trigger as a result of any of the steps for playing a card, that effect waits to resolve until the card and its effect are fully played and resolved. Note that while an action card is resolving, it’s not considered to be in the discard yet." },
    { id: "4.3.4.9", type: "rule", text: "Effects that change how a player pays the cost of a card (e.g., Singer) don’t change the ink cost of the card." },
    { id: "4.3.4.10", type: "rule", text: "If a card can be played “for free,” ignore all ink costs when paying for it. Other steps required to play the card and non-ink costs still apply." },
    { id: "4.3.5", type: "rule", text: "Quest" },
    { id: "4.3.5.1", type: "rule", text: "Sending a character on a quest is a turn action. Only characters can quest." },
    { id: "4.3.5.2", type: "rule", text: "A character chosen to quest is the questing character. The player who declares a questing character is the questing player." },
    { id: "4.3.5.3", type: "rule", text: "To quest, the active player takes the following steps in order." },
    { id: "4.3.5.4", type: "rule", text: "First, the player declares that they’re going to have one of their characters quest." },
    { id: "4.3.5.5", type: "rule", text: "Second, the player identifies the questing character and checks for any restrictions that prevent them from questing (e.g., they aren’t dry yet, they have Reckless, etc.)." },
    { id: "4.3.5.6", type: "rule", text: "If an effect prevents the identified character from questing, that quest is illegal." },
    { id: "4.3.5.7", type: "rule", text: "Third, the player exerts the questing character." },
    { id: "4.3.5.8", type: "rule", text: "If no effect prevents the character from questing, the quest is complete and the questing player gains lore equal to the {L} of the questing character." },
    { id: "4.3.5.9", type: "rule", text: "Effects that would occur as a result of the quest are added to the bag (see 8.7, “Bag”)." },
    { id: "4.3.5.10", type: "rule", text: "Once all effects have been resolved, the quest is over." },
    { id: "4.3.6", type: "rule", text: "Challenge" },
    { id: "4.3.6.1", type: "rule", text: "Sending a character into a challenge is a turn action. Only characters can challenge." },
    { id: "4.3.6.2", type: "rule", text: "A character sent into a challenge is known as a challenging character, and the opposing character or location is being challenged. Both are considered to be in the challenge. Characters can challenge locations. For the differences in that process, see 4.3.6.19." },
    { id: "4.3.6.3", type: "rule", text: "Only the challenging character and the character being challenged are in the challenge. If an ability or effect refers to a character “in a challenge,” it’s referring to one of the two characters in the current challenge." },
    { id: "4.3.6.4", type: "rule", text: "A player who declares a challenging character is the challenging player. The player whose character is being challenged is the challenged player." },
    { id: "4.3.6.5", type: "rule", text: "To challenge, the active player follows the steps listed here, in order." },
    { id: "4.3.6.6", type: "rule", text: "First, the player declares one of their characters is challenging a character. The declared character must have been in play since the beginning of the turn (that is, they must be dry), ready, and otherwise able to challenge." },
    { id: "4.3.6.7", type: "rule", text: "Second, the player chooses an exerted opposing character to be challenged." },
    { id: "4.3.6.8", type: "rule", text: "Third, the players check for challenging restrictions. If any effect prevents the challenge, the challenge is illegal." },
    { id: "4.3.6.9", type: "rule", text: "Fourth, the challenging player exerts the challenging character." },
    { id: "4.3.6.10", type: "rule", text: "Fifth, the challenge occurs." },
    { id: "4.3.6.11", type: "rule", text: "Sixth, “while challenging” effects apply." },
    { id: "4.3.6.12", type: "rule", text: "Seventh, effects that would trigger are added to the bag. This includes effects from abilities that occur “when this character is banished in a challenge” or “when this character is challenged and banished.”" },
    { id: "4.3.6.13", type: "rule", text: "Eighth, once all effects in the bag have resolved, each character deals damage equal to their Strength {S} to the other character. This is known as the “Challenge Damage step.” This isn’t an ability or effect and isn’t added to the bag." },
    { id: "4.3.6.14", type: "rule", text: "To determine the damage each character in the challenge deals, first calculate the total Strength {S} of each, taking into account any current modifier effects. If a character’s {S} is negative, it counts as 0 {S} for the purpose of determining damage." },
    { id: "4.3.6.15", type: "rule", text: "Apply effects that adjust the amount of damage dealt (e.g., Resist)." },
    { id: "4.3.6.16", type: "rule", text: "The resulting number is the final amount of damage that character deals. When damage is dealt to a character, place a number of damage counters equal to that damage on that character. (See 9.1, “Representation of Damage.”)" },
    { id: "4.3.6.17", type: "rule", text: "Any effects that would trigger as a result of a character being banished in or during a challenge that apply trigger and resolve." },
    { id: "4.3.6.18", type: "rule", text: "Once all effects have been resolved and there are no more waiting to be added, effects that apply “while challenging” or “while being challenged” end, and the challenge is over." },
    { id: "4.3.6.19", type: "rule", text: "Players can choose to have a character challenge a location. This follows all of the normal rules and steps of challenging with the following exceptions." },
    { id: "4.3.6.20", type: "rule", text: "When a challenger is declared, the player chooses an opposing location to challenge instead of a character." },
    { id: "4.3.6.21", type: "rule", text: "Locations are never ready or exerted. They can be challenged at any time in the Main Phase." },
    { id: "4.3.6.22", type: "rule", text: "Locations don’t have a Strength {S} characteristic and don’t deal damage to the challenging character." },
    { id: "4.3.6.23", type: "rule", text: "If a character in a challenge is removed from the challenge for any reason, that challenge ends. First, resolve any remaining triggered abilities in the bag. Then, all “while challenging” effects end and the game proceeds to the Main Phase (see 4.3).\n\nExample A: The active player has a ready Stitch – New Dog in play, and an opponent has an exerted Milo Thatch – Clever Cartographer in play. The active player announces Stitch is challenging and chooses Milo Thatch as the character being challenged. There are no restrictions or requirements to satisfy. No effects trigger as a result of these declarations. The active player exerts Stitch. Both Stitch and Milo Thatch deal damage equal to their Strength {S} to the other. The active player and the opponent each place damage counters on their character. A game state check is performed. There are no effects that trigger from the check. The challenge is over.\n\nExample B: The active player declares Marshmallow – Persistent Guardian is challenging an opposing Cheshire Cat – Not All There. Cheshire Cat’s ability Lose Something? reads, “When this character is challenged and banished, banish the challenging character.” Marshmallow’s ability Durable reads, “When this character is banished in a challenge, you may return this card to your hand.” Marshmallow has 5 {S}, so he deals 5 damage to Cheshire Cat, who has 3 {W}. When the game state check is made, Cheshire Cat is banished. This triggers Cheshire Cat’s ability, and the opponent adds it to the bag. The opponent resolves the ability’s effect, banishing Marshmallow. Because the players haven’t reached the step of the challenge in which the bag is resolved, they’re still in the challenge, and Marshmallow’s ability is added to the bag by the active player. The active player can then resolve it, returning Marshmallow to their hand. There are no more effects to add, and the bag is empty. The challenge is over.\n\nExample C: The active player declares Rafiki – Mystical Fighter is challenging an opposing Shenzi – Hyena Pack Leader, who has 0 {S} and is at De Vil Manor – Cruella’s Estate. De Vil Manor has no abilities, but Shenzi’s ability I’ll Handle This gives her +3 {S} while she’s at a location. Rafiki’s ability Ancient Skills reads, “Whenever he challenges a Hyena character, this character takes no damage from the challenge.” After restrictions and requirements are checked, the active player adds this ability to the bag. The active player then resolves that effect. When the challenge proceeds to the Challenge Damage step, Rafiki won’t be dealt any damage." },
    { id: "4.3.7", type: "rule", text: "Move a character to a location." },
    { id: "4.3.7.1", type: "rule", text: "A player can move only their characters. A player can move characters only to their locations. A player can’t move opposing characters, and they can’t move their characters to opposing locations." },
    { id: "4.3.7.2", type: "rule", text: "Moving a character to a location is a turn action. To move a character to a location, the active player follows the steps listed here in order." },
    { id: "4.3.7.3", type: "rule", text: "First, the player chooses one of their characters and one of their locations and declares that the character will move to that location." },
    { id: "4.3.7.4", type: "rule", text: "Second, the player pays the chosen location’s move cost. Once the cost is paid, the character moves to the location." },
    { id: "4.3.7.5", type: "rule", text: "Third, any effects that would happen as a result of the character moving are added to the bag for resolution." },
    { id: "4.3.7.6", type: "rule", text: "Once all effects have been resolved, the move is complete." },
    { id: "4.3.8", type: "rule", text: "Use activated abilities on cards in play." },
    { id: "4.3.8.1", type: "rule", text: "The use of activated abilities is a turn action provided by cards in play. To use the abilities of characters, follow the steps listed in section 7.5, “Activated Abilities.”" },
    { id: "4.3.8.2", type: "rule", text: "{E} abilities of characters can be used only if the character is dry." },
    { id: "4.3.8.3", type: "rule", text: "Activated abilities of items can be used during the turn the item is played." },
    { id: "4.3.8.4", type: "rule", text: "If an activated ability can be used “for free,” ignore all ink costs when paying for it. Other steps required to use the ability and non-ink costs still apply." },
    { id: "4.4", type: "rule", title: "End of Turn Phase" },
    { id: "4.4.1", type: "rule", text: "To end a turn, there must be no abilities currently waiting to resolve. The active player declares the end of their turn. This creates the start of the End of Turn Phase (see 4.1.4)." },
    { id: "4.4.1.1", type: "rule", text: "Effects that would occur “At the end of the turn” and “At the end of your turn” and abilities are added to the bag." },
    { id: "4.4.1.2", type: "rule", text: "Resolve all triggers in the bag." },
    { id: "4.4.1.3", type: "rule", text: "Effects that would end at the end of your turn end. This includes effects with a stated duration of “this turn” (e.g., Support). If this causes any new triggers, return to step 4.4.1.2." },
    { id: "4.4.1.4", type: "rule", text: "The turn ends for the active player, and the next player begins their turn." },

    { id: "5", type: "chapter", title: "Conditions", slug: "conditions" },
    { id: "5.1", type: "rule", title: "General" },
    { id: "5.1.1", type: "rule", text: "Ready – When a card is readied, it’s turned upright and is known as a ready card. Characters and items enter play ready." },
    { id: "5.1.2", type: "rule", text: "Exerted – When a card is exerted, it’s turned sideways. A player can use an exerted card’s abilities that don’t require {E} as part of the cost. A player can’t use any of an exerted card’s abilities that include {E} as part of the cost." },
    { id: "5.1.3", type: "rule", text: "Damaged – A card that has at least 1 damage is considered to be damaged." },
    { id: "5.1.4", type: "rule", text: "Undamaged – A card that has no damage is considered to be undamaged." },
    { id: "5.1.5", type: "rule", text: "Under – A card that has one or more cards on top of it is considered to be under the top card in a stack (see 5.1.7). A player can’t choose any card that’s under the top card (see 5.1.6) in a stack. A card that’s under another card and in the Play zone isn’t considered to be in play. Any player can look at a faceup card that’s under another card at any time. No player can look at the front of a facedown card that’s under another card at any time, not even their own." },
    { id: "5.1.6", type: "rule", text: "On Top – A card that has one or more cards under it is considered to be on top of all cards under it. A card that’s on top of one or more cards doesn’t gain the text of any card under it. The card that’s on top of all other cards in a stack is called the top card." },
    { id: "5.1.7", type: "rule", text: "In a Stack – When a card is on top of or under one or more other cards in play, it and all cards under or on top of it are considered to be in a stack. These cards are considered to be in a stack only while in play. If the top card in a stack leaves play, all cards in the stack move to the same zone as the top card, and these cards are no longer considered to be in a stack." },
    { id: "5.1.8", type: "rule", text: "In Play – A card that’s faceup in the Play zone with no cards on top of it is considered to be in play. If a card is facedown, under another card, or in any zone other than the Play zone, it’s not considered to be in play." },
    { id: "5.1.9", type: "rule", text: "Faceup – A card in the play area with its back (i.e., the side with the Illuminary icon) facing down toward the play surface and its front (i.e., the side with the card’s cost and classifications) facing up toward the players is considered to be faceup. If a card is put under another card faceup or has another card put on top of it while faceup, it’s still considered to be faceup. A card that’s faceup is publicly known to all players. Any player can look at a faceup card at any time, even if the faceup card is under another card." },
    { id: "5.1.10", type: "rule", text: "Facedown – A card in the play area with its back (i.e., the side with the Illuminary icon) facing up toward the players and its front (i.e., the side with the card’s cost and classifications) facing down toward the play surface is considered to be facedown. No player can look at the front of a facedown card at any time, not even their own. A facedown card is never considered to be in play." },
    { id: "5.1.11", type: "rule", text: "Drying – A character that entered play during their player’s turn is considered to be drying. A drying character can’t quest, can’t be declared as a challenging character, and can’t {E} to pay any cost." },
    { id: "5.1.12", type: "rule", text: "Dry – A character that’s been in play since the start of their player’s turn is considered to be dry. A dry character can quest and can be declared as a challenging character. Items and dry characters can {E} to pay any cost." },
    { id: "5.1.13", type: "rule", text: "A card in any zone except a player’s hand can have the condition(s) described below. A card can have multiple conditions at the same time." },
    { id: "5.1.13.1", type: "rule", text: "A character enters play with the ready, undamaged, in play, faceup, and drying conditions. A character that’s in play can have any of the conditions listed in sections 5.1.1 through 5.1.12 except under and facedown." },
    { id: "5.1.13.2", type: "rule", text: "An item enters play with the ready, in play, and faceup conditions. An item that’s in play can’t have the damaged, undamaged, under, or facedown conditions." },
    { id: "5.1.13.3", type: "rule", text: "A location enters play with the undamaged, in play, and faceup conditions. A location that’s in play can’t have the ready, exerted, under, or facedown conditions." },
    { id: "5.1.13.4", type: "rule", text: "A card in a player’s inkwell can only have the ready, exerted, and facedown conditions." },
    { id: "5.1.13.5", type: "rule", text: "A card in a player’s deck can only have the facedown condition." },
    { id: "5.1.13.6", type: "rule", text: "A card in a player’s discard can only have the faceup condition." },
    { id: "5.1.13.7", type: "rule", text: "A card in a player’s hand can’t have any condition." },
    { id: "5.1.14", type: "rule", text: "If a condition is applied to or removed from a card for any reason, the condition is applied or removed immediately.\n\nExample A: The active player decides to quest with a ready Flounder – Voice of Reason. As they exert Flounder to quest, the ready condition is immediately removed from him, and the exerted condition is immediately applied to him.\n\nExample B: The active player decides to play a Tinker Bell – Giant Fairy using her Shift ability on top of a Tinker Bell – Tiny Tactician that’s ready, undamaged, in play, faceup, and dry. As that happens, all conditions except faceup are immediately removed from Tinker Bell – Tiny Tactician and the under and in a stack conditions are immediately applied. The ready, undamaged, on top, in a stack, in play, faceup, and dry conditions are immediately applied to Tinker Bell – Giant Fairy. The ready, undamaged, and dry conditions are immediately applied to the shifted Tinker Bell because the character she’s put on top of already had those conditions. See 10.10 “Shift” for more information." },

    { id: "6", type: "chapter", title: "Card Types", slug: "card-types" },
    { id: "6.1", type: "rule", title: "Characters" },
    { id: "6.1.1", type: "rule", text: "Characters are a type of card that can be in play. A character card that’s in the Play zone is a character; in all other zones it’s a character card." },
    { id: "6.1.2", type: "rule", text: "Characters don’t list “Character” on their classification line. A card needs to have both characteristics outlined in 6.1.2.1 and 6.1.2.2 to be a character. If not, the card isn’t a character." },
    { id: "6.1.2.1", type: "rule", text: "A character has a {S} value and a {W} value." },
    { id: "6.1.2.2", type: "rule", text: "A character has at least one of the following listed on the classification line: Alien, Ally, Broom, Captain, Colossus, Deity, Detective, Dragon, Dreamborn, Entangled, Fairy, Floodborn, Gargoyle, Ghost, Hero, Hunny, Hyena, Illusion, Inventor, King, Knight, Madrigal, Mentor, Musketeer, Pirate, Prince, Princess, Puppy, Queen, Racer, Robot, Seven Dwarfs, Sorcerer, Storyborn, Tigger, Titan, Villain, Whisper." },
    { id: "6.1.3", type: "rule", text: "Only characters can quest or challenge." },
    { id: "6.1.4", type: "rule", text: "A character must have been in play at the beginning of the Set step of their player’s turn in order to quest, challenge, or {E} as part of a cost (see 4.2.2, “Set”)." },
    { id: "6.2", type: "rule", title: "Parts of a Card" },
    { id: "6.2.1", type: "rule", text: "Most parts of a card appear on all card types. Specific differences are noted in the entry for the relevant card type." },
    { id: "6.2.2", type: "rule", text: "Art – The art isn’t used for gameplay." },
    { id: "6.2.3", type: "rule", text: "Ink Type – The ink type of the card, identified by the ink type symbol. The colored bar behind the card’s name reflects the associated color. A card’s ink type is important for building a deck and may be referenced in card rules." },
    { id: "6.2.3.1", type: "rule", text: "Some cards have more than one ink type. Cards with two ink types have two ink type symbols." },
    { id: "6.2.4", type: "rule", text: "Name – The name of the card appears in larger print. An effect that looks for a card or character with a specified name looks only at this line and ignores the version. The whole character or location name must be the same as the specified name to be a match. A character’s or location’s name and version together constitute its full name. (See #2 in the diagram under 6.2, “Parts of a Card.”)\n\nExample A: Tinker Bell – Peter Pan’s Ally has an ability called Loyal and Devoted that reads, “Your characters named Peter Pan gain Challenger +1. (They get +1 {S} while challenging.)” If you have Peter Pan – Fearless Fighter and Peter Pan – Never Land Hero in play with this Tinker Bell, she gives both versions of Peter Pan Challenger +1.\n\nExample B: The Sorcerer’s Hat is an item with an activated ability that lets you name a card, then reveal the top card of your deck and put that card into your hand if it’s the card you named. If you use The Sorcerer’s Hat to look for a card named Lucky and then reveal Lucky Dime, that’s not a match and you don’t get to put it into your hand." },
    { id: "6.2.4.1", type: "rule", text: "Some characters have two names. These characters have an ampersand (&) between the two names listed on the name line. If an effect looks for a card or character with a specified name, the specified name only needs to match one of the two on the character." },
    { id: "6.2.4.2", type: "rule", text: "A character with multiple names is still a single character.\n\nExample: Flotsam & Jetsam is a character that has two names. The card is both a character named “Flotsam” and a character named “Jetsam” in all zones where the card would normally have one name. The names are separated by an ampersand (&) to denote that this character has two names." },
    { id: "6.2.5", type: "rule", text: "Version – A card’s version differentiates cards with the same name. A character’s or location’s name and version together constitute its full name. (See #3 in the diagram under 6.2, “Parts of a Card.”)" },
    { id: "6.2.6", type: "rule", text: "Classifications – Categories that identify some characteristics of the card and may be referenced in card rules. (See #4 in the diagram under 6.2, “Parts of a Card.”)\n\nExample: Hades – King of Olympus has an ability that references cards with the Villain classification. It reads, “This character gets +1 {L} for each other Villain character you have in play.”" },
    { id: "6.2.7", type: "rule", text: "Card Cost – The amount of ink needed to play the card. (See #1 in the diagram under 6.2, “Parts of a Card.”)" },
    { id: "6.2.8", type: "rule", text: "Inkwell Symbol – If this swirl icon, {C}, is present around the card’s cost, the card can be put into its player’s inkwell. Cards in the inkwell are referred to as ink. Each card counts as 1 {I}. (See #1 in the diagram under 6.2, “Parts of a Card.”)" },
    { id: "6.2.9", type: "rule", text: "Strength – Primarily, how much damage this character deals in a challenge, though card effects can also reference this value. Strength {S} only appears on characters. If a character would deal damage equal to its Strength {S} and it has 0 or less Strength {S}, it deals no damage." },
    { id: "6.2.10", type: "rule", text: "Willpower – Damage on a character is persistent, which means it accumulates over the course of the game. If a character has damage equal to or higher than their Willpower {W}, they are banished as a required action. Card effects can also reference this value. (See #6 in the diagram under 6.2, “Parts of a Card.”)" },
    { id: "6.2.11", type: "rule", text: "Lore Value – How much lore the player gains when the character quests. The appearance of the Lore value symbol {L} may vary on some cards (e.g., some enchanted or promo cards), but these variations don’t affect gameplay. (See #8 in the diagram under 6.2, “Parts of a Card.”)" },
    { id: "6.2.12", type: "rule", text: "Abilities – Any abilities the card has appear here. Some abilities have a cost to use them. Abilities can be keywords (see section 10) or have a story name, which is used for referencing the ability but otherwise isn’t used for gameplay. (See #7 in the diagram under 6.2, “Parts of a Card” for where abilities appear on a card. See section 7 for more on abilities.)" },
    { id: "6.2.13", type: "rule", text: "Flavor Text – Flavor text isn’t used for gameplay." },
    { id: "6.2.14", type: "rule", text: "Ancillary Information – Ancillary information isn’t used for gameplay." },
    { id: "6.2.14.1", type: "rule", text: "Artist Name – Artist who illustrated the card." },
    { id: "6.2.14.2", type: "rule", text: "Collector Number – Indicates where this card appears in the set. The number of unique standard cards in the set appears after the slash." },
    { id: "6.2.14.3", type: "rule", text: "Set Number – What number set this card is from.\n\nExample: The First Chapter, Rise of the Floodborn, Into the Inklands, and Ursula’s Return are indicated with 1, 2, 3, and 4 here, respectively." },
    { id: "6.2.14.4", type: "rule", text: "Language – The language the card is in." },
    { id: "6.2.14.5", type: "rule", text: "Legal Text – Copyright information." },
    { id: "6.2.14.6", type: "rule", text: "Rarity Symbol – Indicates how common the card is among the cards in the set it was printed in." },
    { id: "6.3", type: "rule", title: "Actions" },
    { id: "6.3.1", type: "rule", text: "Actions are a type of card that can be played but can’t be in play. An action is an action while being played; otherwise, it’s an action card." },
    { id: "6.3.1.1", type: "rule", text: "An action is defined as having “Action” on the card’s classification line." },
    { id: "6.3.1.2", type: "rule", text: "Actions are played from a player’s hand, but they’re not considered in play. An effect from an action doesn’t enter the bag. (See 8.7, “Bag.”)" },
    { id: "6.3.2", type: "rule", text: "Effects – Actions have effects rather than abilities." },
    { id: "6.3.3", type: "rule", text: "Songs" },
    { id: "6.3.3.1", type: "rule", text: "Songs are actions that have a special rule in addition to the normal rules for actions (see 6.3.3.3)." },
    { id: "6.3.3.2", type: "rule", text: "A song is defined as having “Action” and “Song” on the card’s classification line." },
    { id: "6.3.3.3", type: "rule", text: "All songs allow the player to pay an alternate cost instead of their ink cost to play them. Being a song means “Instead of paying the ink cost of this card, you can {E} one of your characters in play with ink cost N or greater to play this card for free.” This is called singing the song." },
    { id: "6.3.3.4", type: "rule", text: "Some songs also have the keyword Sing Together, which functions similarly to the special rule. (See 10.10, “Sing Together.”)" },
    { id: "6.3.3.5", type: "rule", text: "The standard reminder text for a song is “(A character with cost N or more can {E} to sing this song for free.)”" },
    { id: "6.3.4", type: "rule", text: "Any effect that’s triggered because of an action being played is placed in the bag and will resolve after the effects of the action are fully resolved." },
    { id: "6.4", type: "rule", title: "Items" },
    { id: "6.4.1", type: "rule", text: "Items are a type of card that can be in play. An item is an item only while in the Play zone; in all other zones it’s an item card." },
    { id: "6.4.2", type: "rule", text: "An item is defined as having “Item” on the card’s classification line." },
    { id: "6.4.3", type: "rule", text: "If an item has an ability, that ability can be used during the turn the item is played." },
    { id: "6.5", type: "rule", title: "Locations" },
    { id: "6.5.1", type: "rule", text: "Locations are a type of card that can be in play. A location is a location while in the Play zone; in all other zones it’s a location card." },
    { id: "6.5.2", type: "rule", text: "Classification – A location is defined as having “Location” on the card’s classification line. Locations are the only card type that is printed in landscape (i.e., with the longer sides on the top and bottom). (See #2 on the diagram under 6.5.)" },
    { id: "6.5.3", type: "rule", text: "Cost – A location’s cost is in a different place on the card than the cost of other card types, but it works the same way. (See #1 on the diagram under 6.5.)" },
    { id: "6.5.4", type: "rule", text: "Move Cost – A location has a move cost. This is the amount of ink needed to move a character to this location. (See #3 on the diagram under 6.5.)" },
    { id: "6.5.5", type: "rule", text: "Willpower – Damage on a location is persistent, which means it accumulates over the course of the game. If a location has damage equal to or higher than its Willpower {W}, it’s banished as a required action. Note that locations don’t have a Strength {S} characteristic and don’t deal damage. (See #4 on the diagram under 6.5.)" },
    { id: "6.5.6", type: "rule", text: "Lore Value – A location may have a Lore value {L}, which is how much lore its player gains at the start of their turn during the Set step. (See #6 on the diagram under 6.5.)" },
    { id: "6.5.7", type: "rule", text: "Abilities – If a location has an ability, that ability can be used during the turn the location is played. (See #5 on the diagram under 6.5.)" },

    { id: "7", type: "chapter", title: "Abilities", slug: "abilities" },
    { id: "7.1", type: "rule", title: "General" },
    { id: "7.1.1", type: "rule", text: "Each clause of a card is a separate effect and/or cost. Each clause is separated by a period." },
    { id: "7.1.2", type: "rule", text: "Cards that list one or more costs or effects in a single clause resolve based on the intervening word." },
    { id: "7.1.2.1", type: "rule", text: "Most cards are written as [A].\n\nExample: “You may have up to 99 copies of Dalmatian Puppy – Tail Wagger in your deck.”" },
    { id: "7.1.2.2", type: "rule", text: "[A] to [B] – The player must pay the cost described in the first part of the clause [A]. If they’re unable to do that, they can’t finish resolving the effect in the second part of the clause [B]. The first part of the clause [A] is a cost, not an effect. The second part of the clause [B] is an effect.\n\nExample: “Banish chosen item of yours to deal 5 damage to chosen character.” If the player doesn’t have an item in play that they can banish to pay the cost listed in the first part of the clause [A], they can’t deal the 5 damage described in the second part of the clause [B]." },
    { id: "7.1.2.3", type: "rule", text: "[A] then [B] – Resolve all effects as much as possible, even if some of the effects can’t be resolved.\n\nExample: “Draw 2 cards, then choose and discard 2 cards.”" },
    { id: "7.1.2.4", type: "rule", text: "[A] and [B] – Resolve all effects as much as possible, even if some of the effects can’t be resolved or “and” seems to tie the effects together as though the wording were [A] to [B]. Sometimes “and” simply serves its normal grammatical purpose.\n\nExample A: The Queen – Commanding Presence’s ability Who is the Fairest? reads, “Whenever this character quests, chosen opposing character gets -4 {S} this turn and chosen character gets +4 {S} this turn.” If the opponent doesn’t have a character in play that can be chosen for the first part of this effect, the active player still gives a chosen character +4 {S}.\n\nExample B: John Silver – Greedy Treasure Seeker’s ability Chart Your Own Course reads, “For each location you have in play, this character gains Resist +1 and gets +1 {L}.” This “and” doesn’t have any special gameplay significance." },
    { id: "7.1.3", type: "rule", text: "If an ability or effect contains the word “may,” the player who played the card that generated the effect can choose whether they want it to happen. If the player chooses not to have it happen, no part of the “you may” clause is performed." },
    { id: "7.1.4", type: "rule", text: "If an ability or effect “puts a card into your hand” from any other zone, that is not considered drawing a card." },
    { id: "7.1.5", type: "rule", text: "If an ability or effect refers to “another” or “other,” it refers to a card that any card that effect or ability does not originate from, or one that was not already selected by the ability.\n\nExample: Mulan – Imperial Soldier reads, “During your turn, whenever this character banishes another character in a challenge, your other characters get +1 {L} this turn.” Mulan must banish a character that is not herself, and she doesn’t gain the benefit of this ability herself because it only applies to your “other” characters." },
    { id: "7.1.6", type: "rule", text: "If an ability or effect instructs you to play a card as a part of resolving that ability, you must resolve the ability before playing the card. If the instruction is followed by additional steps for resolving the ability, the card doesn’t resolve or come into play until the ability is fully resolved, even if it’s moved to a different zone.\n\nExample: The active player has an Ursula – Deceiver of All in play and exerts her to sing Friends on the Other Side. Ursula’s ability What a Deal reads, “Whenever this character sings a song, you may play that song again from your discard for free. If you do, put that card on the bottom of your deck instead of into your discard.” Once the song has finished resolving, the player can resolve the triggered ability, which allows them to play Friends on the Other Side again. If they choose to do so, the effect of the song card waits to resolve until Ursula’s triggered ability is resolved fully. Once Friends on the Other Side is put on the bottom of the active player’s deck, then the player draws 2 cards." },
    { id: "7.1.7", type: "rule", text: "Sometimes a combination of abilities can be repeated indefinitely, called a “loop.” If all players are aware of and understand the actions of each iteration of the loop, the player who maintains the loop proposes a specific number of iterations. The game is considered to proceed immediately through those iterations without the player performing each one. Then the game continues and a new action must be taken." },
    { id: "7.1.8", type: "rule", text: "If resolving an effect allows a player to choose “up to” N of something, the player can’t pick the same choice for each iteration of N. “Up to” includes 0 as a legal choice.\n\nExample: The song Painting the Roses Red reads, “Up to 2 chosen characters get -1 {S} this turn. Draw a card.” The same character can’t be chosen twice. The card’s player could also choose 0 characters." },
    { id: "7.1.9", type: "rule", text: "Some abilities and effects use “that” in their text to refer to a specific game term. When resolving abilities and effects, the determination of what “that [Game Term]” refers to occurs after choices are made as the ability or effect is resolving (see 1.2.4).\n\nExample A: Ursula – Deceiver of All’s ability What a Deal reads, “Whenever this character sings a song, you may play that song again from your discard for free. If you do, put that card on the bottom of your deck instead of into your discard.” Here, “that song” refers to the card sung by Ursula and not to any other song card that is in your discard pile.\n\nExample B: Yzma – Above It All has the ability Back to Work, which reads, “Whenever another character is banished in a challenge, return that card to its player’s hand, then that player discards a card at random.” As the effect resolves, Yzma’s player first determines that there are no choices to be made. Then, they determine “that card” is the character banished in a challenge and “that player” is the player whose character is banished. These determinations are made as the effect resolves." },
    { id: "7.1.9.1", type: "rule", text: "If card text references a specific zone where “that” card is put or located, only that zone is checked. If the card referenced by “that” has changed zones, the part of the effect checking the zone for “that” card fails and resolves with no effect, even if there are other cards whose full name matches the full name of “that” card. The player does as much they can when resolving the rest of the effect.\n\nExample: A player has 2 copies of Ursula – Deceiver of All in play and exerts them both to sing a song using its Sing Together ability. Ursula’s ability What a Deal reads, “Whenever this character sings a song, you may play that song again from your discard for free. If you do, put that card on the bottom of your deck instead of into your discard.” Because both copies of Ursula were exerted to sing together, both of their What a Deal abilities are triggered and added to the bag to be resolved. When the first triggered ability resolves, the song card played using Sing Together is put on the bottom of the player’s deck. When the second triggered ability resolves, “that song” card is no longer in the discard, so that part of the effect resolves with no effect. Similarly, “that song” doesn’t refer to a specific song card anymore, so the latter part of the effect also does nothing. Even if there’s another song card with the same name in the discard, “that song” refers only to the specific song card that was sung by Ursula when the triggered abilities were added to the bag, not any other song card with the same name." },
    { id: "7.1.10", type: "rule", text: "Some effects instruct the active player to reveal a card or cards. To reveal a card, the player shows the face of the card to all other players in the game. The player can reveal cards only from the group of cards described earlier in the effect.\n\nExample: The song Look at This Family has an effect that reads, “Look at the top 5 cards of your deck. You may reveal up to 2 character cards and put them into your hand. Put the rest on the bottom of your deck in any order.” The cards the player chooses to reveal can only come from the top 5 cards the player looked at. The player can’t choose to reveal any cards from any other group of cards." },
    { id: "7.2", type: "rule", title: "Action Cards" },
    { id: "7.2.1", type: "rule", text: "Playing an action may trigger other abilities. In this case, the active player resolves the action immediately, and once that action has been fully resolved, players may resolve the triggered abilities as described in section 8.7, “Bag.”" },
    { id: "7.3", type: "rule", title: "Keywords" },
    { id: "7.3.1", type: "rule", text: "Keyword abilities are abilities represented by short names that are the same wherever the ability appears. See section 10, “Keywords,” for more information on individual keyword abilities." },
    { id: "7.3.2", type: "rule", text: "Keywords are usually followed by reminder text describing what they do. This reminder text, enclosed in parentheses and set in italics, is not rules text but only a memory aid." },
    { id: "7.4", type: "rule", title: "Triggered Abilities" },
    { id: "7.4.1", type: "rule", text: "Triggered abilities occur when their trigger condition is met. They trigger only once per trigger condition that is met." },
    { id: "7.4.2", type: "rule", text: "Triggered abilities start with “When,” “Whenever,” “At the start of,” or “At the end of” and describe the game state that causes the abilities to trigger and the effects of the abilities." },
    { id: "7.4.3", type: "rule", text: "When an ability triggers, its effect is placed into the bag to be resolved in order as described in section 8.7, “Bag.”" },
    { id: "7.4.4", type: "rule", text: "Some triggered abilities are written as “[Trigger Condition], if [Secondary Condition], [Effect]. These abilities check whether the secondary condition is true both when the effect would be added to the bag and again when the effect resolves." },
    { id: "7.4.4.1", type: "rule", text: "If the secondary condition is false when the effect would be added to the bag, the effect is never added to the bag." },
    { id: "7.4.4.2", type: "rule", text: "If the secondary condition is false when the effect would resolve, the triggered ability resolves with no effect.\n\nExample: Stitch – Carefree Surfer has an ability called Ohana that reads, “When you play this character, if you have 2 or more other characters in play, you may draw 2 cards.” When the active player plays Stitch, the triggered ability checks to see if the player has two or more other characters in play. If not, the triggered ability isn’t added to the bag. If the player has two or more characters in play, the ability is added to the bag. The triggered ability will check again when it resolves to see if the condition is still true. If it isn’t, the triggered ability resolves for no effect." },
    { id: "7.4.5", type: "rule", text: "Some triggered abilities are written as, “[Trigger Condition], [Effect]. [Effect].” Both effects are linked to the trigger condition but are independent of each other.\n\nExample A: Moana – Of Motunui has an ability called We Can Fix It that reads, “Whenever this character quests, you may ready your other Princess characters. They can’t quest for the rest of this turn.” If the active player chooses to quest with Moana, none of their other Princess characters can quest this turn, regardless of whether they were readied by the effect or not.\n\nExample B: Scar – Vicious Cheater has an ability called Daddy Isn’t Here to Save You that reads, “During your turn, whenever this character banishes another character in a challenge, you may ready this character. He can’t quest for the rest of this turn.” Because the two effects are both tied to the trigger condition, if Scar doesn’t challenge he can quest this turn as normal." },
    { id: "7.4.6", type: "rule", text: "Some triggered abilities are written as, “[Trigger Condition] and [Trigger Condition], [Effect].” These abilities function as having two triggered abilities that are independent of each other but both resolve for the same effect.\n\nExample: John Silver – Alien Pirate has an ability called Pick Your Fights that reads, “When you play this character and whenever he quests, chosen opposing character gains Reckless during their next turn.” The triggered ability occurs when John Silver is played and also when the active player quests with this character. The triggered ability doesn’t need both trigger conditions to be true at the same time for it to occur, only one or the other." },
    { id: "7.4.7", type: "rule", text: "Some abilities and effects create a triggered ability that can occur only during a specific duration or when a specific condition is met at a particular moment later in the game. These are usually created as the result of resolving an action card." },
    { id: "7.4.7.1", type: "rule", text: "Floating Triggered Abilities – Triggered abilities created to exist for a specified duration. These exist outside of the bag. Whenever the condition of the floating triggered ability is met, an instance of that triggered ability is added to the bag for resolution. Once that duration has expired, the floating triggered ability ceases to exist.\n\nExample: Steal from the Rich is an action that reads, “Whenever one of your characters quests this turn, each opponent loses 1 lore.” When Steal from the Rich resolves, it creates the floating triggered ability defined by the card. This exists for the rest of the turn. Whenever the player quests with one of their characters that turn, the condition of the floating triggered ability is met and an instance of that triggered ability is added to the bag to resolve. The floating triggered ability continues to exist outside of the bag until the end of the turn, when the specified duration in the condition expires." },
    { id: "7.4.7.2", type: "rule", text: "Delayed Triggered Abilities – Triggered abilities created to resolve at a specific moment later in the game. This moment is specified in the condition of the delayed triggered ability. The ability exists outside of the bag until that condition is met. When the condition is met, the delayed triggered ability is added to the bag for resolution.\n\nExample: Candy Drift is an action that reads, “Draw a card. Chosen character of yours gets +5 {S} this turn. At the end of your turn, banish them.” When the action resolves, it generates a delayed triggered ability: “At the end of your turn, banish them.” The triggered ability exists outside of the bag until the step of the End of Turn where end-of-turn triggers occur. At that point, the triggered ability is added to the bag and resolves." },
    { id: "7.5", type: "rule", title: "Activated Abilities" },
    { id: "7.5.1", type: "rule", text: "Activated abilities are abilities that a player chooses to use. They are normally written as [Cost] — [Effect]." },
    { id: "7.5.2", type: "rule", text: "While there are no effects waiting to resolve and a character isn’t questing or in a challenge, the active player may use an activated ability." },
    { id: "7.5.3", type: "rule", text: "To use an activated ability, the active player follows these steps in order. If any part of this process can’t be performed, it’s illegal to use the ability. These steps apply to all activated abilities. Only the active player can use activated abilities." },
    { id: "7.5.3.1", type: "rule", text: "First, the active player announces the ability they intend to use." },
    { id: "7.5.3.2", type: "rule", text: "Second, the player follows the steps described in 4.3.4.4 through 4.3.4.6, replacing any instance of the word “card” with the word “ability.”" },
    { id: "7.5.3.3", type: "rule", text: "Once the total cost is paid, the ability is activated. The active player resolves the effect immediately." },
    { id: "7.5.4", type: "rule", text: "If an effect would trigger as a result of any of the steps to using an activated ability, that effect waits to resolve until the ability is fully resolved." },
    { id: "7.6", type: "rule", title: "Static Abilities" },
    { id: "7.6.1", type: "rule", text: "Static abilities are effects that could alter characteristics of a card, game rule, or game state. These are continuously active for the stated length of time. A static ability that doesn’t specify a duration is continuously active for as long as the card generating the effect is in play.\n\nExample: An ability that reads “Your exerted characters gain Ward until end of turn” and an ability that reads “Your exerted characters gain Ward” are both static abilities." },
    { id: "7.6.2", type: "rule", text: "Cards played that would be affected by a static ability have that effect as they come into play. If this modifies their {S} or {W} they are considered to enter play with that adjusted {S} or {W}." },
    { id: "7.6.3", type: "rule", text: "Some static abilities occur as the result of a resolving ability or effect. Once resolved, the static ability continues to apply to the affected cards for the specified duration. Cards that would be affected by a static ability but entered play after the ability or effect is resolved aren’t affected by the static effect." },
    { id: "7.6.4", type: "rule", text: "Some static abilities are part of the characteristics of a card. These static abilities remain “on” as long as the card generating the effect is in play. If a card generating a static ability leaves play, the effect ends as soon as the card is removed from the Play zone. There’s no point at which an affected card will still have the ability and then lose it." },
    { id: "7.6.5", type: "rule", text: "Some static effects apply outside of the Play zone. These specify the aspect and time they apply to.\n\nExample: An effect that reads “For each character card in your discard, you pay 1 {I} less to play this character” would apply outside of play." },
    { id: "7.7", type: "rule", title: "Replacement Effects" },
    { id: "7.7.1", type: "rule", text: "Some effects are considered replacement effects. These effects wait for the stated condition to occur and then partially or completely replace the event as the effect resolves." },
    { id: "7.7.2", type: "rule", text: "Abilities that include the word “instead” are the most common type of replacement effect.\n\nExample: Stolen Scimitar’s ability Slash reads, “{E} — Chosen character gets +1 {S} this turn. If a character named Aladdin is chosen, he gets +2 {S} instead.”" },
    { id: "7.7.3", type: "rule", text: "Abilities that include the word “skip” are replacement effects." },
    { id: "7.7.4", type: "rule", text: "Abilities that include “enter” or “enters” are replacement effects." },
    { id: "7.7.5", type: "rule", text: "Replacement effects happen once and need to exist before the event would occur. If an event is replaced, it never happens. A modified event occurs, and the new event may trigger abilities. Abilities that would have triggered from the original event don’t see it, and therefore they don’t trigger." },
    { id: "7.7.6", type: "rule", text: "Some abilities have replacement effects that partially or completely replace their own abilities, called self-replacement effects. These effects are always applied first." },
    { id: "7.7.7", type: "rule", text: "If multiple instances of different replacement effects can apply to the same event, the player whose cards or card effects are being affected follows the steps listed here." },
    { id: "7.7.7.1", type: "rule", text: "First, if any self-replacement effects can apply, choose one and proceed to section 7.7.7.3. If none can apply, proceed to the next step." },
    { id: "7.7.7.2", type: "rule", text: "Second, if any other replacement effects can apply, choose one." },
    { id: "7.7.7.3", type: "rule", text: "After the chosen replacement effect has been applied, a modified event occurs. Repeat this process, taking into account other replacement effects that can apply to the modified event, until no more replacement effects can apply.\n\nExample: The active player has a Seven Dwarfs’ Mine in play, and the opposing player has a Beast – Selfless Protector and a Flounder – Voice of Reason in play. Seven Dwarfs’ Mine has the ability Mountain Defense, which reads, “During your turn, the first time you move a character here, you may deal 1 damage to chosen character. If the moved character is a Knight, deal 2 damage instead.” Beast – Selfless Protector has the ability Shield Another, which reads, “If one of your other characters would be dealt damage, put that many damage counters on this character instead.” The active player then plays Sleepy – Sluggish Knight, a character with the Knight classification, and moves him to Seven Dwarfs’ Mine. When the location’s triggered ability resolves, the active player chooses to deal damage to Flounder, resulting in the following event: Deal 1 damage to Flounder – Voice of Reason. Replacement effects from Seven Dwarfs’ Mine and Beast can apply to this effect. Flounder is being affected, so the opposing player follows the steps listed in sections 7.7.7.1 through 7.7.7.3. First, the opposing player checks whether there are any self-replacement effects. The Mine’s effect “deal 2 damage instead” is a self-replacement effect that can apply, so the opposing player chooses and applies it. As a result, the modified event is: Deal 2 damage to Flounder – Voice of Reason. The steps are repeated, and the opposing player checks for other self-replacement effects. Finding none, the opposing player moves to the next step and checks for any other replacement effects. Beast – Selfless Protector has a replacement effect that can apply, so the opposing player chooses and applies it, resulting in this event: Put 2 damage counters on Beast – Selfless Protector. The opposing player repeats the steps, but since no replacement effects can apply, the effect resolves and the game continues." },
    { id: "7.7.8", type: "rule", text: "Two or more instances of the same replacement effect can’t apply to the same event. If multiple instances of the same replacement effect could apply to the same event, the player whose cards or card effects are being affected chooses one to apply. The rest cease to exist.\n\nExample: The active player has a Rapunzel – Ready for Adventure, Flounder - Voice of Reason, and 2 copies of Heihei - Boat Snack in play. Rapunzel has a triggered ability called Act of Kindness that reads, “Whenever one of your characters is chosen for Support, until the start of your next turn, the next time they would be dealt damage they take no damage instead.” The active player quests with a Heihei and chooses to add his {S} to Flounder’s {S} with Support, causing Rapunzel’s triggered ability to occur. The ability is added to and resolves from the bag, creating a replacement effect: The next time Flounder would be dealt damage, he takes no damage instead. The active player quests with the other Heihei and chooses to add his {S} to Flounder’s {S} with Support. Rapunzel’s triggered ability is again added to and resolves from the bag, creating another instance of the same replacement effect. The active player exerts Flounder to challenge an opposing exerted character. During the Challenge Damage step, damage is dealt to each character in the challenge, resulting in the following event: The challenged character deals damage equal to their {S} to Flounder. Flounder would be dealt damage, so the active player attempts to apply the two instances of the same replacement effect. Because two or more instances of the same replacement effect can’t apply to the same event, the active player chooses one to apply, resulting in this event: The challenged opposing character deals no damage to Flounder. The remaining instance of the replacement effect can’t apply and ceases to exist." },
    { id: "7.7.9", type: "rule", text: "An effect that skips a step or phase of the game is a replacement effect that replaces that step or phase with nothing. “Skip [Step/Phase]” means the same as “If a player would perform the [Step/Phase], do nothing instead.” If the effect skips a step or phase, no part of that step or phase happens. Any abilities or effects that would occur because of that step or phase don’t happen.\n\nExample: Arthur – Determined Squire has an ability No More Books that reads, “Skip your turn’s Draw step.” When a player would start their Draw step with Arthur in play, they skip their Draw step instead and move immediately to the Main Phase of their turn. However, if a player finds a way to play Arthur during their Draw step, the current Draw step isn’t skipped and proceeds normally." },
    { id: "7.8", type: "rule", title: "Ability Modifiers" },
    { id: "7.8.1", type: "rule", text: "Some abilities and effects can modify the characteristic of a character or location in play, such as {S} or {L}." },
    { id: "7.8.1.1", type: "rule", text: "A modifier applies to a card continuously, either for a fixed length of time or for as long as the card generating the modifier is in play. Whenever a modifier applies to a card’s characteristic, that characteristic changes immediately. This process doesn’t use the bag (see 8.7, “Bag”)." },
    { id: "7.8.1.2", type: "rule", text: "When multiple modifiers apply to a card’s characteristic, they don’t apply in any specific order but all combine to apply together. If a new modifier would apply to a card’s characteristic, it combines with all other modifiers that apply to it.\n\nExample A: The active player plays Grand Duke – Advisor to the King. He has an ability called Yes, Your Majesty that reads, “Your Prince, Princess, King, and Queen characters get +1 {S}.” The +1 {S} modifier generated by the ability’s effect applies immediately to the {S} of all characters the active player has in play with the Prince, Princess, King, and Queen classifications. If that player plays another character with one of these classifications while their Grand Duke is still in play, the new character enters play with the +1 {S} modifier applied and keeps that modification until the Grand Duke leaves play.\n\nExample B: The active player has a Heihei – Rambling Rooster in play with 2 {S} and 2 {W}. Heihei gets +1 {S} from an effect. Heihei now has 3 {S} and 2 {W}. Later in the turn, an additional effect gives Heihei -5 {S}. Heihei’s {S} is modified to be -2 {S}. A later effect gives Heihei +1 {S}, bringing him to -1 {S}. Each time a modifier applies to Heihei, all other modifiers that apply to him combine with it at the same time." },
    { id: "7.8.2", type: "rule", text: "If a character has a negative {S}, it deals no damage during challenges and counts as having a Strength of 0 except for the purpose of applying modifiers to determine its {S} (see 7.8.1.1 and 7.8.1.2).\n\nExample: The active player has a Yokai – Scientific Supervillain and a Microbots in play. Yokai has a triggered ability called Technical Gain that reads, “Whenever this character quests, draw a card for each opposing character with 0 {S}.” Microbots has a triggered ability called Inspired Tech that reads, “When you play this item, chosen character gets -1 {S} this turn for each item named Microbots you have in play.” The opponent has a character with 1 {S} and 1 {W} in play. The active player plays a second Microbots. When resolving the triggered ability, the active player chooses the opponent’s character. It gets -2 {S} and, after this modifier is applied immediately to its {S}, now has -1 {S} and 1 {W}. The active player then quests with Yokai. Because the opposing character’s {S} is negative, the opposing character counts as having a {S} of 0 when resolving Yokai’s triggered ability, and the active player draws 1 card. Even though the character’s {S} counts as 0 for the purpose of resolving Yokai’s effect, it isn’t changed to 0 and still has a {S} of -1." },
    { id: "7.8.3", type: "rule", text: "If a character or location has a negative Lore value {L}, it counts as having a Lore value of 0 except for the purpose of applying modifiers to determine its {L} (see 7.8.1.1 and 7.8.1.2).\n\nExample: The active player has a Flynn Rider – His Own Biggest Fan in play, and their opponent has 5 cards in their hand. Flynn has 4 {L} and an ability called One Last, Big Score that reads, “This character gets -1 {L} for each card in your opponents’ hands.” Because the opponent has 5 cards in their hand, a modifier of -5 applies to Flynn’s Lore value of 4 (-1 for each of the 5 cards). Flynn now has a new Lore value of -1. Because Flynn’s Lore value is negative, if the player exerts him to quest, Flynn counts as having a Lore value of 0 and the player gains 0 lore. This doesn’t change Flynn’s actual Lore value to 0, however. Flynn still has a Lore value of -1 until the number of cards in the opponent’s hand changes or another modifier is applied to his Lore value." },

    { id: "8", type: "chapter", title: "Zones", slug: "zones" },
    { id: "8.1", type: "rule", title: "General" },
    { id: "8.1.1", type: "rule", text: "All zones are considered separate from one another. Some zones may physically be present within the same space but are still separate zones for gameplay purposes.\n\nExample: The table represents the game area of the players. Although the players’ decks, inkwells, and discard piles physically occupy that space, they’re not in play, as they’re all separate zones." },
    { id: "8.1.2", type: "rule", text: "Cards in a public zone are publicly known. Players can look at or count the cards in any public zone at any time." },
    { id: "8.1.3", type: "rule", text: "Cards in a private zone aren’t publicly known. Players can’t look at them unless directed by a game rule (e.g., drawing a card) or an effect. Players can count the number of cards in a private zone at any time. While a private zone is revealed, it’s not considered private." },
    { id: "8.1.4", type: "rule", text: "If an effect allows a player to look at one of their private zones for a specific card or a card of a specific type, they may “fail to find” that card." },
    { id: "8.1.5", type: "rule", text: "If a card enters a private zone from play, any information on or connection to the original card is removed. All effects, damage, and other characteristics are removed and that card becomes a new card." },
    { id: "8.2", type: "rule", title: "Deck" },
    { id: "8.2.1", type: "rule", text: "A player’s deck is where cards they may use in a particular game are held." },
    { id: "8.2.2", type: "rule", text: "The deck is a private zone. The cards in a player’s deck remain facedown at all times and in a single pile. Players can’t look at or change the order of cards in their decks during a game. Players can count the remaining cards in any player’s deck at any time." },
    { id: "8.2.3", type: "rule", text: "Whenever a card or game state instructs a player to draw a card follow the rules outlined in 4.2.3, “Draw.”" },
    { id: "8.2.4", type: "rule", text: "If cards are added to the top or bottom of a deck “in any order” and any of the cards were faceup, the order in which the faceup cards are added to the deck must be known by all players." },
    { id: "8.2.4.1", type: "rule", text: "If those faceup cards are in one or more stacks, and/or any of those stacks contain both faceup and facedown cards, any of the cards in those stacks can be combined and freely ordered with the other cards being added to the deck, including cards in other stacks. No conditions are applied to or removed from those cards until they’re added to the top or bottom of the deck." },
    { id: "8.3", type: "rule", title: "Hand" },
    { id: "8.3.1", type: "rule", text: "A player’s hand is where drawn cards are held. Cards can be added to the hand by other effects as well. Players start the game with a hand of drawn cards (see 3.1, “Starting a Game”)." },
    { id: "8.3.2", type: "rule", text: "The hand is a private zone. Players can look at the cards in their own hand but can’t look at the cards in another player’s hand at any time. Players can count the number of cards in any hand at any time. Players can hold and rearrange their hands in any comfortable and/or convenient fashion." },
    { id: "8.3.3", type: "rule", text: "There’s no maximum hand size. A hand can’t have fewer than 0 cards in it." },
    { id: "8.3.4", type: "rule", text: "If an effect instructs someone to discard, that player chooses the indicated number of cards from their hand and puts them into their discard pile." },
    { id: "8.4", type: "rule", title: "Play" },
    { id: "8.4.1", type: "rule", text: "A player’s Play zone is where their characters, items, and locations are played. Only characters, items, and locations can be in the Play zone. Players can’t play cards into an opponent’s Play zone." },
    { id: "8.4.2", type: "rule", text: "Only cards in a player’s Play zone are considered in play. Cards outside the game aren’t in play. Cards in the bag and those in a player’s deck, discard, hand, and inkwell aren’t in play." },
    { id: "8.4.3", type: "rule", text: "The Play zone is a public zone. Players can look at the cards any player has in play at any time. Players can count the number of cards any player has in play at any time." },
    { id: "8.4.4", type: "rule", text: "Whenever 1 or more cards would leave play, they first check whether any abilities would trigger from them or others leaving play." },
    { id: "8.5", type: "rule", title: "Inkwell" },
    { id: "8.5.1", type: "rule", text: "A player’s inkwell is where they put the cards they will use as ink throughout the game. These cards are ink cards. Each ink card must have the inkwell symbol {C} around its cost and represents 1 {I} the player can use to pay ink costs. Nothing on the front of an ink card affects the ink it generates. There’s no limit to the number of cards a player can have in their inkwell." },
    { id: "8.5.2", type: "rule", text: "Cards are put into a player’s inkwell facedown and ready. If multiple cards are put into a player’s inkwell at the same time, each card is treated as a separate instance." },
    { id: "8.5.3", type: "rule", text: "The inkwell is a private zone. Players can’t look at a card in an inkwell at any time, even their own. Players can count the number of cards in any inkwell at any time." },
    { id: "8.5.4", type: "rule", text: "Players can arrange the cards in their inkwell in any comfortable and convenient fashion, provided that ink cards are kept facedown and separate from cards in all other zones at all times. The number of cards in an inkwell and the number of them that are ready can’t be hidden from other players." },
    { id: "8.5.5", type: "rule", text: "If a card allows a player to put an additional card into their inkwell on their turn, they announce they’re using that effect, then follow the normal steps of putting a card into their inkwell." },
    { id: "8.5.6", type: "rule", text: "Whenever an effect puts a card from another zone into the inkwell, the card isn’t revealed and isn’t required to have the inkwell symbol. It enters the inkwell facedown as ink." },
    { id: "8.6", type: "rule", title: "Discard" },
    { id: "8.6.1", type: "rule", text: "A player’s discard pile is where their cards that have left play are held." },
    { id: "8.6.2", type: "rule", text: "Cards that are banished and action cards that are finished resolving are put into their player’s discard pile." },
    { id: "8.6.3", type: "rule", text: "The discard is a public zone. The cards in a player’s discard remain faceup at all times and in a single pile. Players can look at and count the cards in any player’s discard pile at any time. A player can look at and rearrange the cards in their own discard at any time." },
    { id: "8.6.4", type: "rule", text: "If multiple cards enter a discard pile at the same time, their player adds them in any order." },
    { id: "8.7", type: "rule", title: "Bag" },
    { id: "8.7.1", type: "rule", text: "Unlike other zones, the bag isn’t a physical space but is only where triggered abilities created by the game wait to resolve." },
    { id: "8.7.2", type: "rule", text: "Only triggered abilities can be added to the bag. Activated abilities, resolving actions, and playing characters, locations, or items aren’t added to the bag." },
    { id: "8.7.3", type: "rule", text: "Whenever a triggered ability’s condition is met, the ability is added to the bag by the player who played the card with the triggered ability. If multiple triggered abilities happen at the same time, they’re added to the bag simultaneously by the respective players." },
    { id: "8.7.4", type: "rule", text: "Then the active player chooses and resolves any one of their triggered abilities and fully resolves it. If the resolution of an ability causes another ability to trigger, the new triggered ability is added to the bag once the current ability is finished resolving." },
    { id: "8.7.5", type: "rule", text: "If there are abilities from multiple players in the bag, the active player resolves all of their abilities first, one at a time, including any that were added as a result of resolving abilities." },
    { id: "8.7.6", type: "rule", text: "The next player resolves all of their abilities following the guidelines in 8.7.5. If this causes new triggers, regardless of whose abilities triggered, the current resolving player keeps resolving their triggers." },
    { id: "8.7.7", type: "rule", text: "Continue around the table in turn order as described in 8.7.5–8.7.6 until there are no more triggers to resolve." },
    { id: "8.7.8", type: "rule", text: "Once the bag is empty and all players have no more abilities to resolve or turn actions to take, the players proceed to the next step or phase of the game." },
    { id: "8.7.9", type: "rule", text: "If a player leaves the game while abilities are still waiting in the bag to resolve, those abilities cease to exist." },

    { id: "9", type: "chapter", title: "Damage Counters", slug: "damage-counters" },
    { id: "9.1", type: "rule", title: "Representation of Damage" },
    { id: "9.1.1", type: "rule", text: "Damage on a character is represented by damage counters. Each damage counter normally represents 1 damage; any damage counter intended to represent more than 1 damage counts as a separate damage counter for each 1 damage it represents." },
    { id: "9.2", type: "rule", title: "“Put”" },
    { id: "9.2.1", type: "rule", text: "If an effect puts a damage counter onto a character or location, that doesn’t count as dealing damage to that character or location and isn’t affected by modifications to damage that is dealt (e.g., Resist)." },
    { id: "9.3", type: "rule", title: "Moving Damage Counters" },
    { id: "9.3.1", type: "rule", text: "Moving damage counters has the effect of removing a specified number of counters from a chosen character and putting the same number of damage counters on.\n\nExample: The active player has Simba – Protective Cub in play with 1 damage counter on him. The opponent has The Prince – Never Gives Up (which has Resist +1) in play. The active player plays the action Bestow a Gift which reads, “Move 1 damage counter from chosen character to chosen opposing character.” The player then chooses to move 1 damage counter from Simba to The Prince. The player removes 1 damage counter and puts it on The Prince. The Prince’s Resist keyword ability doesn’t affect this damage as it isn’t damage dealt." },
    { id: "9.4", type: "rule", title: "Leaving Play" },
    { id: "9.4.1", type: "rule", text: "When a card with damage leaves play, when game states are checked all damage counters on it cease to exist." },

    { id: "10", type: "chapter", title: "Keywords", slug: "keywords" },
    { id: "10.1", type: "rule", title: "General" },
    { id: "10.1.1", type: "rule", text: "Keyword abilities provide an ability to the character based on that word. Some abilities stack, or combine; these abilities are followed by “+[N].” A keyword ability that doesn’t have a +[N] doesn’t stack with other effects that provide that keyword.\n\nExample: If you have a character with Support and an effect gives that character Support, only the first instance of the keyword applies. However, if the keywords were Resist +1 and Resist +2, the abilities would stack, and that character would have Resist +3." },
    { id: "10.1.2", type: "rule", text: "The following entries include the technical definitions of keyword abilities. For a more generalized description of keyword abilities see section 7.3, “Keywords.”" },
    { id: "10.1.3", type: "rule", text: "The standard reminder text for each keyword is included here for reference. Reminder text isn’t rules text. It’s only a memory aid and may vary without changing the meaning of keyword rules." },
    { id: "10.2", type: "rule", title: "Alert" },
    { id: "10.2.1", type: "rule", text: "The Alert keyword represents a static ability. Alert means, “This character ignores the challenging restriction of Evasive.”" },
    { id: "10.2.2", type: "rule", text: "The standard reminder text for Alert is, “(This character can challenge as if they had Evasive.)”" },
    { id: "10.2.3", type: "rule", text: "A character doesn’t gain Evasive from having the Alert keyword ability. They can still gain Evasive from another ability or effect." },
    { id: "10.3", type: "rule", title: "Bodyguard" },
    { id: "10.3.1", type: "rule", text: "The Bodyguard keyword represents two abilities." },
    { id: "10.3.2", type: "rule", text: "The first of these is a static ability that functions while the character is being played and creates a replacement effect. This ability means “When you play this character, they may enter play exerted instead of ready.”" },
    { id: "10.3.3", type: "rule", text: "The second is a static ability that creates a challenging restriction. This ability means “If an opponent would choose one of your characters to challenge, they must choose this character or another character with Bodyguard if able.”" },
    { id: "10.3.4", type: "rule", text: "The standard reminder text for Bodyguard is “(This character may enter play exerted. An opposing character who challenges one of your characters must choose one with Bodyguard if able.)”" },
    { id: "10.4", type: "rule", title: "Boost" },
    { id: "10.4.1", type: "rule", text: "The Boost keyword represents an activated ability with a specified duration. Boost N {I} means, “Once during your turn, you may pay N {I} to put the top card of your deck facedown under this card.”" },
    { id: "10.4.2", type: "rule", text: "The standard reminder text for Boost is, “(Once during your turn, you may pay N {I} to put the top card of your deck facedown under this character.)”" },
    { id: "10.4.3", type: "rule", text: "No player can look at the front of a card that has been put facedown under another card at any time, not even their own." },
    { id: "10.4.4", type: "rule", text: "If a card is under another card, it’s not considered to be in play. Putting a card under another card with Boost doesn’t count as playing that card." },
    { id: "10.5", type: "rule", title: "Challenger" },
    { id: "10.5.1", type: "rule", text: "The Challenger keyword represents a static ability that functions while a character is challenging. Challenger +N means “While this character is challenging, they gain +N {S}.” Because this is a +N ability, it stacks with other Challenger effects." },
    { id: "10.5.2", type: "rule", text: "The standard reminder text for Challenger is “(While challenging, this character gets +N {S}.)”" },
    { id: "10.5.3", type: "rule", text: "A character with Challenger doesn’t gain +N {S} if they are being challenged." },
    { id: "10.6", type: "rule", title: "Evasive" },
    { id: "10.6.1", type: "rule", text: "The Evasive keyword represents a static ability that creates a challenging restriction. Evasive means “This character can’t be challenged except by a character with Evasive.”" },
    { id: "10.6.2", type: "rule", text: "The standard reminder text for Evasive is “(Only characters with Evasive can challenge this character.)”" },
    { id: "10.7", type: "rule", title: "Reckless" },
    { id: "10.7.1", type: "rule", text: "The Reckless keyword represents two static abilities." },
    { id: "10.7.2", type: "rule", text: "The first ability means “This character can’t quest.”" },
    { id: "10.7.3", type: "rule", text: "The second ability means “You can’t declare the end of your turn if this character is ready and can challenge an opposing exerted character or location.”" },
    { id: "10.7.4", type: "rule", text: "The standard reminder text for Reckless is “(This character can’t quest and must challenge each turn if able.)”" },
    { id: "10.7.5", type: "rule", text: "A player can still exert a character with Reckless to use its abilities or sing songs." },
    { id: "10.8", type: "rule", title: "Resist" },
    { id: "10.8.1", type: "rule", text: "The Resist keyword represents a static ability that creates a replacement effect. Resist +N means “If damage would be dealt to this character or location, the character or location is dealt that much damage minus N instead.” Because this is a +N ability, this stacks with other Resist effects." },
    { id: "10.8.2", type: "rule", text: "The standard reminder text for a character with Resist is “(Damage dealt to this character is reduced by N.)” The standard reminder text for a location with Resist is “(Damage dealt to this location is reduced by N.)”" },
    { id: "10.8.3", type: "rule", text: "If damage dealt to this character or location is reduced to 0, no damage is considered to have been dealt." },
    { id: "10.9", type: "rule", title: "Rush" },
    { id: "10.9.1", type: "rule", text: "The Rush keyword represents a static ability. Rush means “This character can challenge as though they were in play at the beginning of your turn.”" },
    { id: "10.9.2", type: "rule", text: "The standard reminder text for Rush is “(This character can challenge the turn they’re played.)”" },
    { id: "10.10", type: "rule", title: "Shift" },
    { id: "10.10.1", type: "rule", text: "The Shift keyword represents paying an alternate cost to play a character instead of paying the character’s ink cost. Shift means “If you have a character in play with the same name as this card, you may play this character by paying their Shift cost instead of their ink cost. If you do, put this card on top of another character you have in play with the same name.” This is called shifting." },
    { id: "10.10.2", type: "rule", text: "The standard reminder text for Shift is “(You may [Pay Cost] to play this on top of one of your characters named [Character Name].)”" },
    { id: "10.10.3", type: "rule", text: "If a shifted character is put on top of an exerted character, the shifted character enters play exerted." },
    { id: "10.10.4", type: "rule", text: "If an effect on a shifted character causes it to enter play exerted, it becomes exerted as it enters play, even if the character it was on top of is ready." },
    { id: "10.10.5", type: "rule", text: "If a shifted character is put on top of a dry character, the shifted character enters play dry. If a shifted character is put on top of a drying character, the shifted character enters play drying." },
    { id: "10.10.6", type: "rule", text: "A player can use a shifted character to perform all turn actions of the character it was put on top of. The shifted character doesn’t gain the text of the character it’s put on top of (such as an activated ability), but keeps any effects that apply to that character when the shifted character enters play. A player can exert a shifted character to sing a song if the character it was put on top of was dry." },
    { id: "10.10.7", type: "rule", text: "A shifted character retains whatever damage is on the character it’s put on top of." },
    { id: "10.10.8", type: "rule", text: "When a shifted character leaves play, all cards in its stack (i.e., any cards under it) move to the same zone as the shifted character card does, and the cards are no longer considered to be in a stack (see 5.1.7)." },
    { id: "10.10.9", type: "rule", text: "The Shift keyword has two variants: [Classification] Shift and Universal Shift. These variant keyword abilities are Shift abilities, meaning they follow all rules for the Shift keyword with the following exceptions." },
    { id: "10.10.9.1", type: "rule", text: "[Classification] Shift means “If you have a character in play with the [Classification] specified by this ability, you may play this character by paying their Shift cost instead of their ink cost. If you do, put this card on top of another character you have in play with the specified classification.” The standard reminder text for [Classification] Shift is “(You may [Pay Cost] to play this on top of one of your [Classification] characters.)”" },
    { id: "10.10.9.2", type: "rule", text: "Universal Shift means “If you have a character in play, you may play this character by paying their Shift cost instead of their ink cost. If you do, put this card on top of a character you have in play.” The standard reminder text for Universal Shift is “(You may [Pay Cost] to play this on top of one of your characters.)”" },
    { id: "10.11", type: "rule", title: "Singer" },
    { id: "10.11.1", type: "rule", text: "The Singer keyword represents a static ability that allows a player to pay a lower alternate cost to sing a song. Singer N means “This character can {E} to pay the alternate cost of a song card as though they had cost N instead of their normal ink cost.”" },
    { id: "10.11.2", type: "rule", text: "The standard reminder text for Singer is “(This character counts as cost N to sing songs.)”" },
    { id: "10.11.3", type: "rule", text: "This character counts as cost N only to sing songs and only during the process of playing a card. The character’s ink cost doesn’t change." },
    { id: "10.12", type: "rule", title: "Sing Together" },
    { id: "10.12.1", type: "rule", text: "The Sing Together keyword represents a static ability that allows a player to pay an alternate cost to sing a song with 1 or more of their characters. Sing Together N means “Instead of paying the ink cost of this card, you can {E} a number of your or your teammates’ characters with total ink cost N or greater to play this card without paying its ink cost.”" },
    { id: "10.12.2", type: "rule", text: "The standard reminder text for Sing Together is “(Any number of your or your teammates’ characters with total cost N or more may {E} to sing this song for free.)”" },
    { id: "10.12.3", type: "rule", text: "When playing a song using Sing Together, add the ink costs of one or more of your ready characters together. If the total meets or exceeds the cost listed for Sing Together, the character or characters can sing the song." },
    { id: "10.12.4", type: "rule", text: "When a character sings a song with Sing Together, any triggered abilities on it that have the condition “Whenever this character sings a song” occur when the trigger condition is met." },
    { id: "10.13", type: "rule", title: "Support" },
    { id: "10.13.1", type: "rule", text: "The Support keyword represents a triggered ability. Support means “Whenever this character quests, you may add this character’s {S} to another chosen character’s {S} this turn.”" },
    { id: "10.13.2", type: "rule", text: "The standard reminder text for Support is “(Whenever this character quests, you may add their {S} to another chosen character’s {S} this turn.)”" },
    { id: "10.14", type: "rule", title: "Vanish" },
    { id: "10.14.1", type: "rule", text: "The Vanish keyword represents a triggered ability. Vanish means “When this character is chosen by an opponent as part of resolving an action’s effect, banish this character.”" },
    { id: "10.14.2", type: "rule", text: "The standard reminder text for Vanish is “(When an opponent chooses this character for an action, banish them.)”" },
    { id: "10.14.3", type: "rule", text: "The Vanish triggered ability resolves after the action’s effect resolves. If the character has moved to a different zone before the triggered ability resolves, it resolves with no effect." },
    { id: "10.15", type: "rule", title: "Ward" },
    { id: "10.15.1", type: "rule", text: "The Ward keyword represents a static ability. Ward means “Your opponents can’t choose this card when resolving an effect.”" },
    { id: "10.15.2", type: "rule", text: "The standard reminder text for Ward is “(Opponents can’t choose this character except to challenge.)”" },
    { id: "10.15.3", type: "rule", text: "Effects that don’t require the player to choose still affect a character with Ward." },
  ],
}
